-- Partner locks in both player banks
do
  CharacterReforged_PartnerLock = CharacterReforged_PartnerLock or {}
  local P = CharacterReforged_PartnerLock
  P.ID = "CharacterReforged.partner_lock"
  P.LOCKS = 2231785866
  P.TEXT_GET = 4074371074                            -- CMND_TEXT_GET (text id)
  P.CARD = 1791816279                                -- team00_01_chara_card_for_list (the bank's list cards)
  P.BADGE = 2412626762                               -- character_reforged_partner_badge (the plate layer)
  P.BADGE_TEXT = 4030979030
  P.BADGE_SHEET = 4208557384                         -- #/menu/102_team/team11/team11_05/team11_05.g4tx
  P.BADGE_SLOT = 1514509020                          -- kizuna_base01 (the plate quad's sprite slot)
  P.SPRITE_SWAP = 558735651                          -- (layer, sheet, sprite, slot, 0, instance)
  P.SET_TEXT = 1083631230                            -- CMND_SET_MENU_TEXT_STRING (layer, node, text, instance)
  P.TEXT_VISIBLE = 1505208242                        -- CMND_SET_MENU_TEXT_VISIBLE (layer, node, on, instance)
  P.LAYER_VISIBLE = 711242136                        -- CMND_SET_LAYER_VISIBLE (layer, instance, on)
  P.QUICK_RETIRE_MODE = 5
  P.USES = 286810102
  P.MIX_BADGE = 2510484024
  P.CORNER_MESH = 430313174
  P.CORNER_SHEET = 4225297828                        -- #/menu/102_team/team00/team00_01/<LG>/team00_01.g4tx
  P.CORNER_SLOT = 1685973306                         -- icon_teamdock01 (the mesh's sprite slot = the retail sprite)
  P.MESH_VISIBLE = 3405944500                        -- CMND_SET_MESH_VISIBLE (layer, mesh, on, instance)
  P.STEMS = {"chara_bank_menu", "chara_bank_menu_for_search"}

  function P.reset()
    P.map, P.logged, P.missed = nil, {}, false
    P.uses, P.uses_missed = nil, false               -- card -> { badge, team_badge, partner, system } (nil = not read yet)
    P.badges = {}                                    -- card -> { badge, team_badge } (P.system_badge)
    P.cornered, P.corner_logged = {}, {}             -- list instance wears a badge sprite; card's badge is in the log
  end
  P.reset()

  function P.log(...)
    P.logger = P.logger or VRFW.logger.new("partner_lock")
    P.logger(...)
  end

  -- Reads the map card to { base, sprite, textId, text }.
  function P.read_map()
    if P.map ~= nil then
      return P.map
    end
    local ok, list = pcall(funcLuaCommand, P.LOCKS)
    if not ok or type(list) ~= "table" then
      P.missed = true
      return nil
    end
    local map, n = {}, 0
    for _, e in pairs(list) do
      if type(e) == "table" and type(e[1]) == "number" and e[1] ~= 0 then
        map[e[1]] = {base = e[2] or 0, sprite = e[3] or 0, text_id = e[4] or 0, text = e[5]}
        n = n + 1
      end
    end
    P.map = map
    P.log("locks", n)
    return map
  end

  function P.of(card)
    if type(card) ~= "number" or card == 0 then
      return nil
    end
    local map = P.read_map()
    return map ~= nil and map[card] or nil
  end

  function P.read_uses()
    if P.uses ~= nil then
      return P.uses
    end
    local ok, list = pcall(funcLuaCommand, P.USES)
    if not ok or type(list) ~= "table" then
      P.uses_missed = true
      return nil
    end
    local map, n = {}, 0
    for _, e in pairs(list) do
      if type(e) == "table" and type(e[1]) == "number" and e[1] ~= 0 then
        map[e[1]] = {badge = type(e[2]) == "number" and e[2] or 0, partner = e[4] == true, system = tostring(e[5] or "?"),
          team_badge = type(e[6]) == "number" and e[6] or 0}
        n = n + 1
      end
    end
    P.uses = map
    P.log("uses", n)
    return map
  end

  -- Returns a card's badge from a stored pair, otherwise from its mix slot move.
  function P.system_badge(card)
    if type(card) ~= "number" or card == 0 then
      return 0, 0
    end
    local known = P.badges[card]
    if known ~= nil then
      return known[1], known[2]
    end
    local uses = P.read_uses()
    if uses == nil then
      return 0, 0
    end
    local use = uses[card]
    local badge, team_badge = 0, 0
    if use ~= nil then
      badge, team_badge = use.badge, use.team_badge
    else
      local ok, b, t = pcall(funcLuaCommand, P.MIX_BADGE, card)
      if ok then
        badge, team_badge = type(b) == "number" and b or 0, type(t) == "number" and t or 0
      end
    end
    P.badges[card] = {badge, team_badge}
    return badge, team_badge
  end

  function P.paint_corner(layer, instance, card, badge, team_badge)
    if layer ~= P.CARD or type(instance) ~= "number" then
      return
    end
    if badge ~= 0 then
      local sprite = badge
      if team_badge ~= 0 and type(IsCharaInAnyTeam) == "function" and IsCharaInAnyTeam(card) then
        sprite = team_badge
      end
      local oks = pcall(funcLuaMenuCommand, P.SPRITE_SWAP, P.CARD, P.CORNER_SHEET, sprite, P.CORNER_SLOT, 0, instance)
      local okv = pcall(funcLuaMenuCommand, P.MESH_VISIBLE, P.CARD, P.CORNER_MESH, true, instance)
      P.cornered[instance] = true
      if not P.corner_logged[card] then
        P.corner_logged[card] = true
        P.log("corner badge", string.format("%08X", card), instance, string.format("%08X", sprite), oks, okv)
      end
    elseif P.cornered[instance] then
      pcall(funcLuaMenuCommand, P.SPRITE_SWAP, P.CARD, P.CORNER_SHEET, P.CORNER_SLOT, P.CORNER_SLOT, 0, instance)
      P.cornered[instance] = nil
    end
  end

  function P.word(e)
    if type(e.text) == "string" and e.text ~= "" then
      return e.text
    end
    if e.text_id ~= 0 then
      local ok, s = pcall(funcLuaCommand, P.TEXT_GET, e.text_id)
      if ok and type(s) == "string" and s ~= "" then
        return s
      end
    end
    return nil
  end

  -- the plate on list card `instance` (hidden for a free card, an empty instance or a system without a plate)
  function P.paint(layer, instance, card)
    if layer ~= P.CARD or type(instance) ~= "number" then
      return
    end
    local e = P.of(card)
    local picker = CharacterReforged_BankMoves ~= nil and CharacterReforged_BankMoves.created == true
    local shown = e ~= nil and e.sprite ~= 0 and not picker
    if shown then
      pcall(funcLuaMenuCommand, P.SPRITE_SWAP, P.BADGE, P.BADGE_SHEET, e.sprite, P.BADGE_SLOT, 0, instance)
      local word = P.word(e)
      if word ~= nil then
        pcall(funcLuaMenuCommand, P.SET_TEXT, P.BADGE, P.BADGE_TEXT, word, instance)
      end
      pcall(funcLuaMenuCommand, P.TEXT_VISIBLE, P.BADGE, P.BADGE_TEXT, word ~= nil, instance)
      if not P.logged[card] then
        P.logged[card] = true
        P.log("plate", string.format("%08X", card), string.format("%08X", e.base), instance)
      end
    end
    pcall(funcLuaMenuCommand, P.LAYER_VISIBLE, P.BADGE, instance, shown)
  end

  function P.mode()
    local ok, v = pcall(function()
      return VRFW.host.hosts.chara_bank_menu.L.n18
    end)
    if ok then
      return v
    end
    return nil
  end

  if VRFW.host ~= nil then
    for _, stem in ipairs(P.STEMS) do
      VRFW.host.on(stem, "OnInit", {id = P.ID .. ".init", phase = "before", fn = function()
        P.reset()
      end})
      VRFW.host.on(stem, "Step", {id = P.ID .. ".retry", phase = "after", fn = function()
        if P.uses == nil and P.uses_missed and P.read_uses() ~= nil then
          P.uses_missed = false
          P.badges = {}
          local bank = CharacterReforged_BankMoves
          if bank ~= nil then
            bank.status, bank.refusal_logged = {}, {}
          end
          if UpdateList ~= nil then
            pcall(UpdateList)
          end
        end
        if P.map == nil and P.missed then
          local map = P.read_map()
          if map ~= nil then
            P.missed = false
            if next(map) ~= nil and UpdateList ~= nil then
              pcall(UpdateList)
            end
          end
        end
      end})
      VRFW.host.on(stem, "UpdateCharaCard", {id = P.ID .. ".plate", phase = "after", fn = function(r, layer, instance, card)
        P.paint(layer, instance, card)
      end})
    end

    -- Hooks the player bank.
    VRFW.host.on("chara_bank_menu", "UpdateCharaCard", {id = P.ID .. ".corner", phase = "after",
      fn = function(r, layer, instance, card)
        local badge, team_badge = P.system_badge(card)
        P.paint_corner(layer, instance, card, badge, team_badge)
      end})

    -- Hooks the team dock's bank.
    VRFW.host.on("chara_bank_menu", "IsBankCharaEnabled", {id = P.ID .. ".disabled", phase = "around",
